export function getConfusionPairsForSurah(surahNumber: number): ConfusionPair[] {
  return CONFUSION_PAIRS.filter(
    (p) => p.ayahA.surah === surahNumber || p.ayahB.surah === surahNumber,
  );
}

export function getMemorizationLinksForSurah(surahNumber: number): MemorizationLink[] {
  return MEMORIZATION_LINKS.filter(
    (l) => l.sourceSurah === surahNumber || l.targetSurah === surahNumber,
  );
}

export function getStoryRecurrence(storyId: string): StoryRecurrenceEntry | undefined {
  return STORY_RECURRENCES.find((r) => r.storyId === storyId);
}
